  /// <summary>
  /// Identifies whether a transcription was produced by an automatic
  /// speech-to-text system or by a human annotator.
  /// </summary>
  public enum TranscriptionType {
    /// <summary>
    /// Sentinel value when the source of the transcription was not specified.
    /// </summary>
    [pbr::OriginalName("TRANSCRIPTION_TYPE_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Automatic transcription produced by a speech-to-text system.
    /// </summary>
    [pbr::OriginalName("TRANSCRIPTION_TYPE_S2T")] S2T = 1,
    /// <summary>
    /// Manual transcription produced by a human annotator.
    /// </summary>
    [pbr::OriginalName("TRANSCRIPTION_TYPE_HUMAN")] Human = 2,
  }

  /// <summary>
  /// Effort level for reasoning models (e.g. o1, o3). Controls the trade-off
  /// between speed and quality.
  /// </summary>
  public enum ReasoningEffort {
    /// <summary>
    /// Unspecified reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Minimal reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_MINIMAL")] Minimal = 1,
    /// <summary>
    /// Low reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_LOW")] Low = 2,
    /// <summary>
    /// Medium reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_MEDIUM")] Medium = 3,
    /// <summary>
    /// High reasoning effort.
    /// </summary>
    [pbr::OriginalName("REASONING_EFFORT_HIGH")] High = 4,
  }

  /// <summary>
