    [pbr::OriginalName("LLM_SAFETY_LOCATION_INPUT")] Input = 1,
    /// <summary>
    /// The finding was matched in the model output (completion).
    /// </summary>
    [pbr::OriginalName("LLM_SAFETY_LOCATION_OUTPUT")] Output = 2,
  }

  /// <summary>
  /// Audio encoding of the audio content sent in the conversational query request.
  /// Refer to the &lt;a href="/speech/docs/basics">Cloud Speech API documentation&lt;/a> for more details.
  /// </summary>
  public enum AudioEncoding {
    /// <summary>
    /// Not specified.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_UNSPECIFIED")] Unspecified = 0,
    /// <summary>
    /// Uncompressed 16-bit signed little-endian samples (Linear PCM).
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_LINEAR_16")] Linear16 = 1,
    /// <summary>
    /// &lt;a href="https://xiph.org/flac/documentation.html">FLAC&lt;/a> (Free Lossless Audio
    /// Codec) is the recommended encoding because it is lossless (therefore
    /// recognition is not compromised) and requires only about half the
    /// bandwidth of &lt;code>LINEAR16&lt;/code>. &lt;code>FLAC&lt;/code> stream encoding supports 16-bit and
    /// 24-bit samples, however, not all fields in &lt;code>STREAMINFO&lt;/code> are supported.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_FLAC")] Flac = 2,
    /// <summary>
    /// 8-bit samples that compand 14-bit audio samples using G.711 PCMU/mu-law.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_MULAW")] Mulaw = 3,
    /// <summary>
    /// Adaptive Multi-Rate Narrowband codec. &lt;code>sample_rate_hertz&lt;/code> must be 8000.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_AMR")] Amr = 4,
    /// <summary>
    /// Adaptive Multi-Rate wideband codec. &lt;code>sample_rate_hertz&lt;/code> must be 16000.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_AMR_WB")] AmrWb = 5,
    /// <summary>
    /// Opus encoded audio frames in Ogg container
    /// (&lt;a href="https://wiki.xiph.org/OggOpus">OggOpus&lt;/a>).
    /// &lt;code>sample_rate_hertz&lt;/code> must be 16000.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_OGG_OPUS")] OggOpus = 6,
    /// <summary>
    /// Although the use of lossy encodings is not recommended, if a very low
    /// bitrate encoding is required, &lt;code>OGG_OPUS&lt;/code> is highly preferred over
    /// Speex encoding. The &lt;a href="https://speex.org/">Speex&lt;/a> encoding supported by
    /// Dialogflow API has a header byte in each block, as in MIME type
    /// &lt;code>audio/x-speex-with-header-byte&lt;/code>.
    /// It is a variant of the RTP Speex encoding defined in
    /// &lt;a href="https://tools.ietf.org/html/rfc5574">RFC 5574&lt;/a>.
    /// The stream is a sequence of blocks, one block per RTP packet. Each block
    /// starts with a byte containing the length of the block, in bytes, followed
    /// by one or more frames of Speex data, padded to an integral number of
    /// bytes (octets) as specified in RFC 5574. In other words, each RTP header
    /// is replaced with a single byte containing the block length. Only Speex
    /// wideband is supported. &lt;code>sample_rate_hertz&lt;/code> must be 16000.
    /// </summary>
    [pbr::OriginalName("AUDIO_ENCODING_SPEEX_WITH_HEADER_BYTE")] SpeexWithHeaderByte = 7,
  }

  /// <summary>
  /// Type of operator to compare
  /// </summary>
  public enum ComparisonOperator {
    /// <summary>
    /// equal operator
    /// </summary>
    [pbr::OriginalName("EQUAL")] Equal = 0,
    /// <summary>
    /// greater operator, e.g. for numbers, dates, and strings
    /// </summary>
    [pbr::OriginalName("GREATER")] Greater = 1,
    /// <summary>
    /// greater or equal operator, e.g. for numbers, dates, and strings
    /// </summary>
    [pbr::OriginalName("GREATER_OR_EQUAL")] GreaterOrEqual = 2,
    /// <summary>
    /// less or equal operator, e.g. for numbers, dates, and strings
    /// </summary>
    [pbr::OriginalName("LESS_OR_EQUAL")] LessOrEqual = 3,
    /// <summary>
    /// contains operator, e.g. part of string, or one of the elements in an iterable such as set or list
    /// </summary>
    [pbr::OriginalName("CONTAINS")] Contains = 4,
    /// <summary>
    /// starts with operator for string comparison only
    /// </summary>
    [pbr::OriginalName("STARTS_WITH")] StartsWith = 5,
    /// <summary>
    /// ends with operator for string comparison only
    /// </summary>
    [pbr::OriginalName("ENDS_WITH")] EndsWith = 6,
  }

